1. 信号量P、V操作实现互斥与同步的代码如下：

```c
#define BUFFER_SIZE 1000
#define CONSUMER_COUNT 10

// 信号量定义
semaphore mutex = 1; // 用于互斥访问缓冲区
semaphore empty = BUFFER_SIZE; // 缓冲区空闲位置数量
semaphore full = 0; // 缓冲区已存放产品数量
int buffer[BUFFER_SIZE]; // 缓冲区
int in = 0; // 缓冲区输入位置
int out = 0; // 缓冲区输出位置

// 生产者进程
void producer() {
    while (1) {
        // 生产产品
        int product = produce_product();

        P(empty); // 等待缓冲区有空位
        P(mutex); // 进入临界区
        buffer[in] = product; // 放入产品
        in = (in + 1) % BUFFER_SIZE; // 更新输入位置
        V(mutex); // 离开临界区
        V(full); // 增加缓冲区产品数量
    }
}

// 消费者进程
void consumer() {
    int count = 0; // 连续取出产品数量
    while (1) {
        P(full); // 等待缓冲区有产品
        P(mutex); // 进入临界区
        int product = buffer[out]; // 取出产品
        out = (out + 1) % BUFFER_SIZE; // 更新输出位置
        V(mutex); // 离开临界区
        V(empty); // 增加缓冲区空位数量

        // 连续取出10件产品
        if (++count == CONSUMER_COUNT) {
            count = 0; // 重置连续取出产品数量
            // 等待其他消费者进程取出产品
            while (count < CONSUMER_COUNT) {
                P(empty); // 等待缓冲区有空位
                P(mutex); // 进入临界区
                out = (out + 1) % BUFFER_SIZE; // 更新输出位置
                V(mutex); // 离开临界区
                V(full); // 增加缓冲区产品数量
                count++;
            }
        }
    }
}

// 生产产品函数
int produce_product() {
    // ... 生产产品逻辑 ...
    return product;
}
```

2. 信号量含义和初值：
- `mutex`：互斥信号量，用于保证缓冲区在任一时刻只有一个进程可以访问，初值为1。
- `empty`：缓冲区空闲位置数量信号量，表示缓冲区中空闲位置的数量，初值为缓冲区大小。
- `full`：缓冲区已存放产品数量信号量，表示缓冲区中已存放产品的数量，初值为0。
